    }),
  });
};

const toDateString = (date) => date.toISOString().slice(0, 10);

const getDayIndex = (date) =>
  date.getDay() === 0 ? 6 : date.getDay() - 1;

const addDays = (date, days) => {
  const result = new Date(date);
  result.setDate(result.getDate() + days);
